class Solution:
    def equalizeWater(self, buckets: List[int], loss: int) -> float:
        lo, hi = 0.0, float(max(buckets))
        r = 1 - loss / 100
        for _ in range(100):
            mid = (lo + hi) / 2
            surplus = deficit = 0.0
            for b in buckets:
                if b > mid:
                    surplus += b - mid
                else:
                    deficit += mid - b
            if surplus * r >= deficit:
                lo = mid
            else:
                hi = mid
        return lo

