class Solution:
    def equalizeWater(self, buckets: List[int], loss: int) -> float:
        b = sorted(buckets)
        n = len(b)
        r = 1 - loss / 100
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + b[i]
        total = pre[n]
        for k in range(n + 1):
            x = (r * (total - pre[k]) + pre[k]) / (k + r * (n - k))
            low = b[k - 1] if k > 0 else 0.0
            high = b[k] if k < n else float('inf')
            if low <= x <= high:
                return x
        return float(b[-1])

