class Solution {
public:
    double equalizeWater(vector<int>& buckets, int loss) {
        int n = buckets.size();
        vector<double> b(buckets.begin(), buckets.end());
        sort(b.begin(), b.end());
        double r = 1 - loss / 100.0;
        vector<double> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + b[i];
        double total = pre[n];
        for (int k = 0; k <= n; k++) {
            double x = (r * (total - pre[k]) + pre[k]) / (k + r * (n - k));
            double low = k > 0 ? b[k - 1] : 0.0;
            double high = k < n ? b[k] : numeric_limits<double>::infinity();
            if (x >= low && x <= high) return x;
        }
        return b[n - 1];
    }
};

