var equalizeWater = function(buckets, loss) {
    const b = [...buckets].sort((x, y) => x - y);
    const n = b.length;
    const r = 1 - loss / 100;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + b[i];
    const total = pre[n];
    for (let k = 0; k <= n; k++) {
        const x = (r * (total - pre[k]) + pre[k]) / (k + r * (n - k));
        const low = k > 0 ? b[k - 1] : 0;
        const high = k < n ? b[k] : Infinity;
        if (x >= low && x <= high) return x;
    }
    return b[n - 1];
};
